  "orderedSteps": [
    {
      "id": "D13-ESTATE",
      "steps": [
        "Fix personal estate list excluding institutional assets and persons.",
        "Mark existing liens, reservations and disputes.",
        "If law/valid testament/authorized whole allocation missing, retain prior owner and held record; never distribute residue equally.",
        "For explicitly authorized eligible whole assets transfer title only; preserve quantity, custodian, location, route, use rights, reservation, lien.",
        "Record delivery obligation separately; no inventory addition.",
        "Retain recorded personal obligor and estate-review debt; never blanket heir liability."
      ]
    },
    {
      "id": "D13-SPLIT",
      "steps": [
        "Require divisible parent and exactly two fresh child identities.",
        "Check child atom sets are disjoint and their union equals parent atoms; units identical.",
        "Preserve title, custody, rights, reservations, liens, route and location in children.",
        "Retire parent to immutable history; count only active child stock."
      ]
    },
    {
      "id": "D13-RESERVE",
      "steps": [
        "Proposal alone never reserves.",
        "Require registered price and accepted contract snapshot; no V<=W automatic acceptance.",
        "Revalidate authority, same snapshot and unique asset identities/atoms.",
        "On valid acceptance atomically reserve all requested assets, or preserve all previous reservations on conflict.",
        "Competing acceptance gets typed conflict and explicit re-proposal requirement; no queue."
      ]
    },
    {
      "id": "D13-DELIVERY",
      "steps": [
        "Legal title alone cannot alter location or custody.",
        "Verified actual arrival plus designated recipient confirmation, valid identity/custody/rights and applicable conditions completes receipt.",
        "No mandatory separate custodian signature added: stronger two-party conjunction remains proposal.",
        "Confirmed arrival <= cutoff is eligible at that cutoff; late arrival never changes past cutoff.",
        "Failure receipt stays physically local/quarantined and unavailable; missing delivery keeps reservation.",
        "Preserve completed receipt against later failed retry or blockade; distinct admitted events follow D18 causal/ingress ordering."
      ]
    },
    {
      "id": "D13-OBLIGATIONS",
      "steps": [
        "Keep personal/office/institution attachment distinct.",
        "Land loss does not erase organization identity, treasury, debt or obligations.",
        "Missing lawful representative/custodian/dissolution clause produces held state, not deletion.",
        "Evaluate actual signed continue/end/ratify clause; record legal effect and physical handover separately.",
        "No new debt priority, interest, automatic recall, return or heir reassignment."
      ]
    }
  ],
  "formulaSheet": [
    {
      "id": "D13-F-CONSERVATION",
      "expression": "atoms(parent)=disjointUnion(atoms(child1),atoms(child2)); Qparent=Q1+Q2; active parent count=0",
      "unit": "same material atoms",
      "source": "GP-06/split-provenance-A; sp1.b65",
      "rounding": "none; atom counts exact; fractional shares not inferred",
      "clamp": "none; omissions or duplicate atoms invalid"
    },
    {
      "id": "D13-F-ESTATE",
      "expression": "personalEstate=assignedWholeAssets disjointUnion heldAssets; institutions excluded; Qbefore=Qafter",
      "unit": "same material unit per asset class, never sum heterogeneous currencies as value",
      "source": "sp1.b64-b67; allocation-A",
      "rounding": "none; indivisible assets whole only",
      "clamp": "none; shares/residue ratio held"
    },
    {
      "id": "D13-F-CUTOFF",
      "expression": "eligibleAtCutoff = completedReceipt AND arrival<=cutoff; finalAvailable additionally requires unreserved/usable rights and applicable stock conditions",
      "unit": "same approved clock unit; fixture-clock only for cases",
      "source": "economy-owner.20261003.arrival; receiver confirmation",
      "rounding": "none",
      "clamp": "none; null time unresolved"
    },
    {
      "id": "D13-F-VALUATION",
      "expression": "V=sum(demanded prices)-sum(offered prices) on same war/proposal snapshot",
      "unit": "D17 registered price unit; null unresolved",
      "source": "sp1.b126; D12",
      "rounding": "D17-specific held; no invented coefficient",
      "clamp": "none; V<=W never automatic acceptance"
    }
  ],
  "rng": {
    "scope": "none for D13 identity/title/conservation guards; no random beneficiary, debt allocation or price"
  },
  "time": {
    "estate": "admitted death event",
    "delivery": "admitted physical arrival/receiver receipt; common daily cutoff imported from D18",
    "reservation": "explicit accepted offer, never nonbinding proposal",
    "exactClockScalePhase": "held under GP-06/D22"
